using System.ComponentModel.DataAnnotations;

namespace DocSummary.Models;

public class SummarizeRequest
{
    [Required]
    [MinLength(1)]
    public string DocumentText { get; set; } = string.Empty;

    /// <summary>
    /// Maximum number of sentences in the summary. Defaults to 3.
    /// </summary>
    [Range(1, 20)]
    public int MaxSentences { get; set; } = 3;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public string Summary { get; set; } = string.Empty;
    public int OriginalWordCount { get; set; }
    public int SummaryWordCount { get; set; }
}

namespace DocSummary.Services;

public interface IDocumentSummaryService
{
    Models.SummarizeResponse Summarize(string documentText, int maxSentences);
}

/// <summary>
/// Extractive summarizer that scores sentences by word-frequency relevance
/// and returns the top-ranked ones in their original order.
/// </summary>
public class DocumentSummaryService : IDocumentSummaryService
{
    private static readonly char[] SentenceDelimiters = ['.', '!', '?'];

    public Models.SummarizeResponse Summarize(string documentText, int maxSentences)
    {
        var sentences = SplitSentences(documentText);

        if (sentences.Count == 0)
        {
            return new Models.SummarizeResponse
            {
                Summary = string.Empty,
                OriginalWordCount = 0,
                SummaryWordCount = 0
            };
        }

        var selectedSentences = sentences.Count <= maxSentences
            ? sentences
            : RankAndSelect(sentences, maxSentences);

        var summary = string.Join(" ", selectedSentences);

        return new Models.SummarizeResponse
        {
            Summary = summary,
            OriginalWordCount = WordCount(documentText),
            SummaryWordCount = WordCount(summary)
        };
    }

    private static List<string> SplitSentences(string text)
    {
        var sentences = new List<string>();
        int start = 0;

        for (int i = 0; i < text.Length; i++)
        {
            if (SentenceDelimiters.Contains(text[i]))
            {
                var sentence = text[start..(i + 1)].Trim();
                if (sentence.Length > 0)
                    sentences.Add(sentence);
                start = i + 1;
            }
        }

        // Trailing text without a sentence-ending delimiter
        var trailing = text[start..].Trim();
        if (trailing.Length > 0)
            sentences.Add(trailing);

        return sentences;
    }

    private static List<string> RankAndSelect(List<string> sentences, int maxSentences)
    {
        var wordFrequency = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

        foreach (var sentence in sentences)
        {
            foreach (var word in GetWords(sentence))
            {
                wordFrequency.TryGetValue(word, out int count);
                wordFrequency[word] = count + 1;
            }
        }

        // Score each sentence by the sum of its word frequencies
        var scored = sentences
            .Select((s, index) => new
            {
                Index = index,
                Sentence = s,
                Score = GetWords(s).Sum(w => wordFrequency.GetValueOrDefault(w, 0))
            })
            .OrderByDescending(x => x.Score)
            .Take(maxSentences)
            .OrderBy(x => x.Index) // preserve original order
            .Select(x => x.Sentence)
            .ToList();

        return scored;
    }

    private static IEnumerable<string> GetWords(string text) =>
        text.Split(' ', StringSplitOptions.RemoveEmptyEntries)
            .Select(w => w.Trim('.', ',', '!', '?', ';', ':', '"', '\'', '(', ')'));

    private static int WordCount(string text) =>
        text.Split(' ', StringSplitOptions.RemoveEmptyEntries).Length;
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummarizeController : ControllerBase
{
    private readonly IDocumentSummaryService _summaryService;

    public SummarizeController(IDocumentSummaryService summaryService)
    {
        _summaryService = summaryService;
    }

    [HttpPost]
    public ActionResult<SummarizeResponse> Summarize([FromBody] SummarizeRequest request)
    {
        var result = _summaryService.Summarize(request.DocumentText, request.MaxSentences);
        return Ok(result);
    }
}

