+            }
+        }
+
+        // Trailing text without a sentence-ending delimiter
+        var trailing = text[start..].Trim();
+        if (trailing.Length > 0)
+            sentences.Add(trailing);
+
+        return sentences;
+    }
+
+    private static List<string> RankAndSelect(List<string> sentences, int maxSentences)
+    {
+        var wordFrequency = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
+
+        foreach (var sentence in sentences)
+        {
+            foreach (var word in GetWords(sentence))
+            {
+                wordFrequency.TryGetValue(word, out int count);
+                wordFrequency[word] = count + 1;
+            }
+        }
+
+        // Score each sentence by the sum of its word frequencies
+        var scored = sentences
+            .Select((s, index) => new
+            {
+                Index = index,
+                Sentence = s,
+                Score = GetWords(s).Sum(w => wordFrequency.GetValueOrDefault(w, 0))
+            })
+            .OrderByDescending(x => x.Score)
+            .Take(maxSentences)
+            .OrderBy(x => x.Index) // preserve original order
+            .Select(x => x.Sentence)
+            .ToList();
+
+        return scored;
+    }
+
+    private static IEnumerable<string> GetWords(string text) =>
+        text.Split(' ', StringSplitOptions.RemoveEmptyEntries)
+            .Select(w => w.Trim('.', ',', '!', '?', ';', ':', '"', '\'', '(', ')'));
+
+    private static int WordCount(string text) =>
+        text.Split(' ', StringSplitOptions.RemoveEmptyEntries).Length;
+}
